class Node:
  def __init__(self, val, left=None, right=None):
    self.val = val
    self.left = left
    self.right = right

def most_stacked(root):
  pos_to_count = dict()

  def visit(node, r, c):
    if not node:
      return
    if (r, c) not in pos_to_count:
      pos_to_count[(r, c)] = 0
    pos_to_count[(r, c)] += 1
    visit(node.left, r + 1, c)
    visit(node.right, r, c + 1)

  visit(root, 0, 0)
  return max(pos_to_count.values())

