function mostStacked(root) {
  const posToCount = new Map();

  function visit(node, r, c) {
    if (!node) {
      return;
    }
    const key = `${r},${c}`;
    posToCount.set(key, (posToCount.get(key) || 0) + 1);
    visit(node.left, r + 1, c);
    visit(node.right, r, c + 1);
  }

  visit(root, 0, 0);
  return Math.max(...posToCount.values());
}

